#include <stdio.h>
int main()
{
int a[5][5], b[5][5];
for(int i = 0; i < 5; i++) // 输入a数组
    for(int j = 0; j < 5; j++)
        scanf('%d', &a[i][j]);
for(int i = 0; i < 5; i++) // 转置矩阵
    for(int j = 0; j < 5; j++)
        b[j][i] = a[i][j];
FILE* fp;
if((fp = fopen('matrix.txt', 'wb')) ==NULL)
{
    perror('输入错误');
    return 1;
}
for(int i = 0; i < 5; i++)
{
    fwrite(b[i], sizeof(int), 5, fp); // 按行输入;
    fputc('\n');//换行
}
fclose(fp); // 关闭文件
return 0;
}

